a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'summary.csv'));d<-s[s$type=='cell',];labs<-c('Original food\nFixed age','Original food\nStaggered ages','Limited food\nFixed age','Limited food\nStaggered ages');keys<-c('0.05 fixed','0.05 staggered','0.025 fixed','0.025 staggered')
png(file.path(p,'contrasts.png'),width=1400,height=850,res=160);par(mar=c(7,5,3,1));ylim<-range(c(0,d$lower,d$upper),finite=TRUE);plot(NA,xlim=c(.5,4.5),ylim=ylim,xaxt='n',xlab='',ylab='Mixture minus mean of eight controls (agents)',main='Independent policy-mixture replication');abline(h=0,lty=2,col='gray50');axis(1,at=1:4,labels=labs,tick=FALSE,line=.2);cols<-c('#2166ac','#b2182b');for(j in 1:2){t<-c(800,1000)[j];v<-d[match(paste(keys,t),paste(d$label,d$tick)),];x<-1:4+c(-.09,.09)[j];arrows(x,v$lower,x,v$upper,angle=90,code=3,length=.04,col=cols[j]);points(x,v$mean,pch=c(16,17)[j],col=cols[j],cex=1.2)};legend('topleft',legend=c('Tick 800','Tick 1,000'),pch=c(16,17),col=cols,bty='n');mtext('Points: paired means; bars: 95% intervals',side=1,line=5.2,cex=.8);dev.off()
